CREATE TABLE IF NOT EXISTS richo_quality_invariants(id uuid PRIMARY KEY,name text NOT NULL UNIQUE,description text,severity text NOT NULL,scope text NOT NULL,checker text,status text NOT NULL DEFAULT 'active',correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_quality_assurance_runs(id uuid PRIMARY KEY,release_id text NOT NULL,summary jsonb NOT NULL,results jsonb NOT NULL,correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_contract_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contract_key text NOT NULL,consumer text NOT NULL,provider text NOT NULL,status text NOT NULL,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,verified_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_synthetic_journeys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),journey_key text NOT NULL,environment text NOT NULL,status text NOT NULL,steps jsonb NOT NULL,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,executed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_fault_injection_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scenario text NOT NULL,target text NOT NULL,status text NOT NULL,severity text NOT NULL,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,executed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_flaky_test_stats(test_key text PRIMARY KEY,runs integer NOT NULL DEFAULT 0,failures integer NOT NULL DEFAULT 0,flake_rate numeric(8,6) NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
